const msg = $json.message || {};
const chatId = String(msg.chat?.id || '');
const rawText = (msg.text || '').trim().replace(/^\/\w+\s*/, '').trim();

const coordMatch = rawText.match(/^(-?\d+\.?\d*),\s*(-?\d+\.?\d*)$/);

if (coordMatch) {
  return [{ json: {
    chatId,
    lat: parseFloat(coordMatch[1]),
    lng: parseFloat(coordMatch[2]),
    locationLabel: coordMatch[1].trim() + ', ' + coordMatch[2].trim(),
    needsGeocode: false
  }}];
} else if (rawText && rawText.length > 1) {
  return [{ json: {
    chatId,
    cityQuery: rawText,
    lat: null,
    lng: null,
    locationLabel: rawText,
    needsGeocode: true
  }}];
} else {
  return [{ json: {
    chatId,
    lat: 35.6528,
    lng: -97.4781,
    locationLabel: 'Oklahoma City, OK',
    needsGeocode: false
  }}];
}

const geoRaw = $input.first().json;
const geoArr = Array.isArray(geoRaw) ? geoRaw : [geoRaw];
const result = geoArr[0];
const parsed = $('Parse Input').first().json;
const chatId = parsed.chatId;

if (result && result.lat) {
  return [{ json: {
    chatId,
    lat: parseFloat(result.lat),
    lng: parseFloat(result.lon),
    locationLabel: result.display_name
  }}];
}

return [{ json: {
  chatId,
  lat: 35.6528,
  lng: -97.4781,
  locationLabel: 'Oklahoma City, OK (location not found)'
}}];

let lat, lng, chatId, locationLabel;

try {
  const sc = $('Set Coords').first().json;
  if (sc && sc.lat != null) {
    lat = sc.lat; lng = sc.lng; chatId = sc.chatId; locationLabel = sc.locationLabel;
  }
} catch(e) {}

if (lat == null) {
  const pi = $('Parse Input').first().json;
  lat = pi.lat; lng = pi.lng; chatId = pi.chatId; locationLabel = pi.locationLabel;
}

return [{ json: { lat, lng, chatId, locationLabel } }];

const aq = $('Fetch Air Quality').first().json;
const pollen = $('Fetch Pollen').first().json;
const ctx = $('Resolve Context').first().json;
const chatId = ctx.chatId;
const locationLabel = ctx.locationLabel;

// --- AQI ---
const indexes = aq.indexes || [];
const aqiEntry = indexes.find(i => i.code === 'usa_epa') || {};
const aqi = aqiEntry.aqi != null ? aqiEntry.aqi : 'N/A';
const aqiCategory = aqiEntry.category || 'Unknown';

// --- Pollutants ---
const pollutantMap = {};
(aq.pollutants || []).forEach(p => { pollutantMap[p.code] = p.concentration || {}; });
const pm25 = pollutantMap.pm25 && pollutantMap.pm25.value != null ? pollutantMap.pm25.value.toFixed(1) : 'N/A';
const pm10 = pollutantMap.pm10 && pollutantMap.pm10.value != null ? pollutantMap.pm10.value.toFixed(1) : 'N/A';
const o3 = pollutantMap.o3 && pollutantMap.o3.value != null ? pollutantMap.o3.value.toFixed(1) : 'N/A';

// --- Pollen ---
const pollenMap = {};
((pollen.dailyInfo || [])[0]?.pollenTypeInfo || []).forEach(p => { pollenMap[p.code] = p.indexInfo || {}; });

const catEmoji = (cat) => {
  const m = { 'None': '\u26AA', 'Very Low': '\uD83D\uDFE2', 'Low': '\uD83D\uDFE2', 'Moderate': '\uD83D\uDFE1', 'High': '\uD83D\uDFE0', 'Very High': '\uD83D\uDD34' };
  return m[cat] || '\u26AA';
};
const pollenLabel = (info) => {
  if (!info || info.value == null) return '\u26AA N/A';
  return catEmoji(info.category) + ' ' + (info.category || 'N/A') + ' (' + info.value + '/5)';
};
const aqiEmoji = (cat) => {
  const c = (cat || '').toLowerCase();
  if (c.includes('good')) return '\uD83D\uDFE2 ' + cat;
  if (c.includes('moderate')) return '\uD83D\uDFE1 ' + cat;
  if (c.includes('sensitive')) return '\uD83D\uDFE0 ' + cat;
  if (c.includes('very unhealthy')) return '\uD83D\uDFE3 ' + cat;
  if (c.includes('unhealthy')) return '\uD83D\uDD34 ' + cat;
  if (c.includes('hazardous')) return '\u26AB ' + cat;
  return '\u26AA ' + cat;
};

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'America/Chicago'
});

const msg = '\uD83C\uDF24 <b>Air Quality Report \u2014 ' + today + '</b>\n\uD83D\uDCCD ' + locationLabel + '\n\n\uD83C\uDF0D <b>Overall AQI:</b> ' + aqi + ' \u2014 ' + aqiEmoji(aqiCategory) + '\n\uD83D\uDCA8 <b>PM2.5:</b> ' + pm25 + ' \u00B5g/m\u00B3\n\uD83C\uDF2B <b>PM10:</b> ' + pm10 + ' \u00B5g/m\u00B3\n\uD83E\uDDEA <b>Ozone:</b> ' + o3 + ' ppb\n\n\uD83C\uDF3F <b>Pollen (0\u20135 scale)</b>\n\uD83C\uDF33 <b>Tree:</b> ' + pollenLabel(pollenMap.TREE) + '\n\uD83C\uDF3E <b>Grass:</b> ' + pollenLabel(pollenMap.GRASS) + '\n\uD83C\uDF31 <b>Weed:</b> ' + pollenLabel(pollenMap.WEED) + '\n\n\u2139\uFE0F Source: Google Air Quality &amp; Pollen APIs';

return [{ json: { message: msg, chatId } }];
